WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT s.id, s.account_id, s.txn_type, s.txn_time, s.merchant, s.is_flagged, s.session_start_flag, s.island_id, CASE WHEN merchant RLIKE '^(Amazon|Shell)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS merchant_zone, (SELECT SUM(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS sum_transaction_amount FROM sessions_transactions s ORDER BY merchant DESC NULLS LAST
